import React, { useEffect, useState } from 'react';
import axios from 'axios';



export default function Translate({ text }) {
  const [translated, setTranslated] = useState('');
  useEffect(() => {
    setTranslated('');
    const input = text.trim();
    if (!input) return;
    let active = true;
    const cancellation = axios.CancelToken.source();
    const timer = setTimeout(async () => {
      try {
        const { data } = await axios.get(
          'https://functions.yandexcloud.net/d4es5cgl7anep55j3rrl',
          { params: { text: input }, cancelToken: cancellation.token }
        );
        
        const translation = data.translation;
        if (active) setTranslated(translation ? translation : 'Перевод не найден');
      } catch (error) {
        if (active && !axios.isCancel(error)) setTranslated('Не удалось получить перевод');
      }
    }, 300);
    return () => {
      active = false;
      clearTimeout(timer);
      cancellation.cancel();
    };
  }, [text]);
  return <h1 aria-live="polite">{translated}</h1>;
}

